<?php
require __DIR__.'/bootstrap.php';requireAuth();if(!canManageSettings()){http_response_code(403);exit('No autorizado.');}
$error='';$notice='';$values=['whatsapp_phone'=>'','whatsapp_enabled'=>'0','store_ready'=>'0','currency'=>'PYG'];
try{$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){if(!validCsrf())throw new RuntimeException('La sesión venció.');$phone=preg_replace('/\D+/','',(string)($_POST['whatsapp_phone']??''));$wa=isset($_POST['whatsapp_enabled'])?'1':'0';$ready=isset($_POST['store_ready'])?'1':'0';$confirm=trim((string)($_POST['confirm_enable']??''));if(($wa==='1'||$ready==='1')){if(!preg_match('/^\d{10,15}$/',$phone))throw new RuntimeException('Para habilitar la tienda o WhatsApp cargá un número válido.');if($confirm!=='HABILITAR')throw new RuntimeException('Para habilitar funciones comerciales escribí HABILITAR en la confirmación.');}foreach(['whatsapp_phone'=>$phone,'whatsapp_enabled'=>$wa,'store_ready'=>$ready,'currency'=>'PYG'] as $k=>$v){$q=$pdo->prepare('INSERT INTO settings (`key`,`value`) VALUES (?,?) ON DUPLICATE KEY UPDATE `value`=VALUES(`value`)');$q->execute([$k,$v]);}auditLog($pdo,'settings.update','settings',null,['store_ready'=>$ready,'whatsapp_enabled'=>$wa]);header('Location: /admin/settings.php?saved=1',true,303);exit;}$rows=$pdo->query("SELECT `key`,`value` FROM settings WHERE `key` IN ('whatsapp_phone','whatsapp_enabled','store_ready','currency')")->fetchAll(PDO::FETCH_KEY_PAIR);$values=array_merge($values,$rows);if(isset($_GET['saved']))$notice='Configuración guardada.';}catch(Throwable $e){error_log('InYou settings: '.$e->getMessage());$error=$e instanceof PDOException?'Falta aplicar la migración 002_admin_settings.sql.':$e->getMessage();}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Configuración · InYou</title><link rel="stylesheet" href="/admin/style.css"><style>.wrap{max-width:900px;margin:auto}.panel{background:#fff;border:1px solid #e7e5df;border-radius:12px;padding:22px;margin:20px 0}.field{display:block;margin:16px 0}.field span{display:block;font-weight:600;margin-bottom:7px}.input{width:100%;padding:11px;border:1px solid #d9d8d3;border-radius:7px}.btn{background:#202321;color:#fff;border:0;border-radius:7px;padding:12px 16px}.alert{padding:12px;border-radius:8px;background:#e4f2e9}.error{background:#f9e6e4}</style></head><body class="dashboard"><?php adminSidebar('settings');?><main class="content"><div class="wrap"><header><div>Hola, <?=h($_SESSION['admin_name']??'Administrador')?></div></header><div class="eyebrow">CONFIGURACIÓN</div><h1>Tienda y WhatsApp</h1><p>La tienda permanece bloqueada hasta una activación explícita.</p><?php if($error):?><div class="alert error"><?=h($error)?></div><?php endif;?><?php if($notice):?><div class="alert"><?=h($notice)?></div><?php endif;?><section class="panel"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label class="field"><span>WhatsApp Business</span><input class="input" name="whatsapp_phone" value="<?=h($values['whatsapp_phone'])?>" placeholder="595981123456"></label><label class="field"><input type="checkbox" name="whatsapp_enabled" value="1" <?=$values['whatsapp_enabled']==='1'?'checked':''?>> Habilitar botón de WhatsApp</label><label class="field"><input type="checkbox" name="store_ready" value="1" <?=$values['store_ready']==='1'?'checked':''?>> Tienda lista para recibir consultas</label><label class="field"><span>Confirmación de activación</span><input class="input" name="confirm_enable" placeholder="Escribí HABILITAR solo si querés activar"></label><p><small>Si las dos casillas quedan desmarcadas, podés guardar sin escribir HABILITAR.</small></p><button class="btn">Guardar configuración</button></form></section></div></main></body></html>